async def generic(flag: bool, items: list[str]):
    if (await corpus.echo("a") if flag else "b"):
        result = "yes"
    else:
        result = "no"
    while (await corpus.echo("go") if flag else False):
        flag = False
    else:
        result = "stopped"
    for item in (items if flag else []):
        result = item
    else:
        result = "walked"
    check = lambda value: value if flag else None
    return [result, check(result)]
